                 \/ (PMSPA.o_tb AD fb + 1 <= dptr /\ dptr + n <= PMSPA.o_tb AD fb + 24) \/ (dptr = 0 /\ l = [])
                 \/ (PMSPA.aobjA FF dptr n /\ (dptr + n <= fb \/ fb + 2048 <= dptr)).   (* [comment removed for export] *)
